namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryValidateIdentity(principal, resource, request, out var validationFailure))
            return validationFailure;
        if (TryValidateRequestState(principal!, resource!, request!, out validationFailure))
            return validationFailure;

        var facts = GatherAuthorizationFacts(principal!, resource!, request!, delegations);

        if (TryDecideBreakGlass(request!, facts, out var decision))
            return decision;
        if (TryEnforceResourceRequirements(resource!, request!, out decision))
            return decision;
        if (TryDenyDelete(request!, facts, out decision))
            return decision;
        if (TryDenyWrite(request!, facts, out decision))
            return decision;
        if (TryDenyRead(request!, facts, out decision))
            return decision;
        if (TryDenyUnknownAction(request!, out decision))
            return decision;

        return CreateSuccessfulDecision(resource!, request!, facts);
    }

    private static bool TryValidateIdentity(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision decision)
    {
        if (principal is null || resource is null || request is null)
        {
            decision = new AccessDecision(false, "missing-context", true);
            return true;
        }

        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
        {
            decision = new AccessDecision(false, "invalid-identity", true);
            return true;
        }

        if (principal.Suspended)
        {
            decision = new AccessDecision(false, "principal-suspended", true);
            return true;
        }

        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
        {
            decision = new AccessDecision(false, "tenant-mismatch", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryValidateRequestState(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Locked && request.Action != "read")
        {
            decision = new AccessDecision(false, "resource-locked", true);
            return true;
        }

        if (request.MinuteOfDay is < 0 or > 1439)
        {
            decision = new AccessDecision(false, "invalid-time", true);
            return true;
        }

        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "challenge-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static AuthorizationFacts GatherAuthorizationFacts(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        return new AuthorizationFacts(
            principal.Roles.Contains("administrator"),
            principal.Roles.Contains("operator"),
            principal.Roles.Contains("auditor"),
            principal.Id == resource.OwnerId,
            delegations.HasDelegation(principal.Id, resource.Id, request.Action));
    }

    private static bool TryDecideBreakGlass(
        AccessRequest request,
        AuthorizationFacts facts,
        out AccessDecision decision)
    {
        if (!request.BreakGlass)
        {
            decision = default!;
            return false;
        }

        decision = !facts.Administrator || !request.StrongAuthentication
            ? new AccessDecision(false, "invalid-break-glass", true)
            : new AccessDecision(true, "break-glass", true);
        return true;
    }

    private static bool TryEnforceResourceRequirements(
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "strong-authentication-required", true);
            return true;
        }

        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
        {
            decision = new AccessDecision(false, "trusted-network-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryDenyDelete(
        AccessRequest request,
        AuthorizationFacts facts,
        out AccessDecision decision)
    {
        if (request.Action == "delete" && !facts.Administrator)
        {
            decision = new AccessDecision(false, "administrator-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryDenyWrite(
        AccessRequest request,
        AuthorizationFacts facts,
        out AccessDecision decision)
    {
        if (request.Action == "write" && !facts.CanWrite)
        {
            decision = new AccessDecision(false, "write-not-authorised", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryDenyRead(
        AccessRequest request,
        AuthorizationFacts facts,
        out AccessDecision decision)
    {
        if (request.Action == "read" && !facts.CanRead)
        {
            decision = new AccessDecision(false, "read-not-authorised", false);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryDenyUnknownAction(AccessRequest request, out AccessDecision decision)
    {
        if (request.Action is not ("read" or "write" or "delete"))
        {
            decision = new AccessDecision(false, "unknown-action", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static AccessDecision CreateSuccessfulDecision(
        Resource resource,
        AccessRequest request,
        AuthorizationFacts facts)
    {
        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            facts.Delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private readonly struct AuthorizationFacts
    {
        public AuthorizationFacts(
            bool administrator,
            bool operatorRole,
            bool auditor,
            bool owner,
            bool delegated)
        {
            Administrator = administrator;
            OperatorRole = operatorRole;
            Auditor = auditor;
            Owner = owner;
            Delegated = delegated;
        }

        public bool Administrator { get; }
        public bool OperatorRole { get; }
        public bool Auditor { get; }
        public bool Owner { get; }
        public bool Delegated { get; }
        public bool CanWrite => Administrator || OperatorRole || Owner || Delegated;
        public bool CanRead => Administrator || OperatorRole || Auditor || Owner || Delegated;
    }
}
